-- Teacher-precomputed artifact; no Python is required in class.
CREATE TABLE IF NOT EXISTS embedding_artifact_meta (artifact_id VARCHAR(64) PRIMARY KEY, model_id VARCHAR(120) NOT NULL, model_revision CHAR(40) NOT NULL, preprocessing_id VARCHAR(100) NOT NULL, dimension INT NOT NULL, normalized TINYINT NOT NULL, source_hash CHAR(64) NOT NULL, payload_hash CHAR(64) NOT NULL);
DELETE FROM embedding_artifact_meta;
CREATE TABLE IF NOT EXISTS query_vectors (case_id VARCHAR(8) PRIMARY KEY, query_text TEXT NOT NULL, content_hash CHAR(64) NOT NULL, embedding VECTOR(512) NOT NULL);
DELETE FROM query_vectors;
SELECT artifact_id,model_id,dimension,normalized FROM embedding_artifact_meta;
SELECT COUNT(*) AS query_count FROM query_vectors;
